  width: 200px;
  height: 150px;
}

/* Example: creating a long text block */
.long-text {
    font-size: 16px;
    line-height: 1.5;
    /* This text will be long enough to overflow */
}

/* Example of setting overflow to visible */
.container {
  overflow: visible;
}

/* Example: changing overflow value */
.container {
  width: 300px;
  height: 200px;
  overflow: hidden;
}

/* Example of using overflow: scroll */
.container {
  width: 300px;
  height: 200px;
  overflow: scroll;
}

